changeSet.sql:
INSERT INTO parser (name, description, dataset_name, list_type, website_url, plugin_id, plugin_url, data_source_type, parser_kind, source_location, parameters, refresh_hours, retention_months, licence, attribution, notes, enabled, created_at) VALUES ('PEP Allemagne – Cours des comptes fédérale et régionales', 'Présidents, vice-présidents et membres dirigeants de la Cour des comptes fédérale et des 16 cours régionales (catégorie DE-e)', 'de_pep_audit_courts', 'PEP', 'https://www.bundesrechnungshof.de', 'de-pep-audit-courts', 'D:/test parser 2/plugins/swiftcheck-aml-de-pep-audit-courts-0.0.1-SNAPSHOT.jar', 'PLUGIN_MANAGED', 'WEB_PAGE', NULL, '{"configFile": ""}', 168, 12, 'Citer la source (Bundesrechnungshof / Landesrechnungshöfe)', 'Bundesrechnungshof und Landesrechnungshöfe', 'Configuration-driven : lit les pages des collèges dirigeants de la Cour fédérale et des 16 cours des Länder.', TRUE, NOW());
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'Président, vice-président et membres du collège du Bundesrechnungshof.', NULL FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'DE-e' AND f.label LIKE 'Président, vice-président ou membre de la Cour des comptes fédérale%' AND p.dataset_name = 'de_pep_audit_courts';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'Présidents, vice-présidents et directoires des 16 cours des comptes régionales (Landesrechnungshöfe).', NULL FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'DE-e' AND f.label LIKE 'Président, vice-président ou membre d''une cour des comptes de Land%' AND p.dataset_name = 'de_pep_audit_courts';

INSERT INTO parser (name, description, dataset_name, list_type, website_url, plugin_id, plugin_url, data_source_type, parser_kind, source_location, parameters, refresh_hours, retention_months, licence, attribution, notes, enabled, created_at) VALUES ('PEP Allemagne – Juges des cours fédérales suprêmes', 'Juges des 6 cours fédérales suprêmes : BVerfG, BGH, BVerwG, BAG, BSG, BFH (catégorie DE-d)', 'de_pep_federal_courts', 'PEP', 'https://www.bundesverfassungsgericht.de', 'de-pep-federal-courts', 'D:/test parser 2/plugins/swiftcheck-aml-de-pep-federal-courts-0.0.1-SNAPSHOT.jar', 'PLUGIN_MANAGED', 'WEB_PAGE', NULL, '{"configFile": ""}', 168, 12, 'Citer les sources respectives des cours fédérales', 'Oberste Gerichtshöfe des Bundes', 'Extrait les juges fédéraux des 6 hautes juridictions : Cour constitutionnelle (BVerfG, 16 juges) et cours de justice suprêmes.', TRUE, NOW());
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'Les 16 juges de la Cour constitutionnelle fédérale (BVerfG), présidents et vice-présidents de sénats.', NULL FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'DE-d' AND f.label LIKE 'Juge à la Cour constitutionnelle fédérale%' AND p.dataset_name = 'de_pep_federal_courts';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'Présidents et juges à la Cour fédérale de justice (BGH).', NULL FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'DE-d' AND f.label LIKE '%Cour fédérale de justice%' AND p.dataset_name = 'de_pep_federal_courts';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'Présidents et juges à la Cour administrative fédérale (BVerwG).', NULL FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'DE-d' AND f.label LIKE '%Cour administrative fédérale%' AND p.dataset_name = 'de_pep_federal_courts';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'Présidents et juges à la Cour fédérale des finances (BFH).', NULL FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'DE-d' AND f.label LIKE '%Cour fédérale des finances%' AND p.dataset_name = 'de_pep_federal_courts';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'Présidents et juges à la Cour fédérale du travail (BAG).', NULL FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'DE-d' AND f.label LIKE '%Cour fédérale du travail%' AND p.dataset_name = 'de_pep_federal_courts';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'Présidents et juges à la Cour sociale fédérale (BSG).', NULL FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'DE-d' AND f.label LIKE '%Cour sociale fédérale%' AND p.dataset_name = 'de_pep_federal_courts';
